-- =====================================================================
--  Proyecto : Sistema de Reserva de Salas Universitario  (LM_RESERVASALAS)
--  Script   : 02_insertar_datos.sql
--  Ejecutar : conectado como LM_RESERVASALAS, despues de 01_crear_tablas.sql
--  Contenido: datos iniciales (mas de 10 registros por tabla)
-- =====================================================================
SET ECHO OFF
SET DEFINE OFF
WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK
ALTER SESSION SET NLS_DATE_FORMAT = 'YYYY-MM-DD HH24:MI';

-- ---------------- FACULTAD (12) ----------------

-- ---------------- USUARIO (14) ----------------

-- ---------------- EDIFICIO (12) ----------------

-- ---------------- TIPO_ESPACIO (12) ----------------

-- ---------------- ESPACIO (15) ----------------

-- ---------------- RECURSO (12) ----------------

-- ---------------- ESPACIO_RECURSO (24) ----------------

-- ---------------- RESERVA (18) ----------------

COMMIT;

-- Ajustar las columnas IDENTITY para que el proximo ID siga al maximo cargado
ALTER TABLE FACULTAD     MODIFY ID_FACULTAD GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE USUARIO      MODIFY ID_USUARIO  GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE EDIFICIO     MODIFY ID_EDIFICIO GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE TIPO_ESPACIO MODIFY ID_TIPO     GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE ESPACIO      MODIFY ID_ESPACIO  GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE RECURSO      MODIFY ID_RECURSO  GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE RESERVA      MODIFY ID_RESERVA  GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
-- El ALTER de RESERVA invalida su trigger de reglas: se recompila
ALTER TRIGGER TRG_RESERVA_REGLAS COMPILE;

SET ECHO ON
SELECT 'FACULTAD' TABLA, COUNT(*) REGISTROS FROM FACULTAD UNION ALL
SELECT 'USUARIO',         COUNT(*) FROM USUARIO         UNION ALL
SELECT 'EDIFICIO',        COUNT(*) FROM EDIFICIO        UNION ALL
SELECT 'TIPO_ESPACIO',    COUNT(*) FROM TIPO_ESPACIO    UNION ALL
SELECT 'ESPACIO',         COUNT(*) FROM ESPACIO         UNION ALL
SELECT 'RECURSO',         COUNT(*) FROM RECURSO         UNION ALL
SELECT 'ESPACIO_RECURSO', COUNT(*) FROM ESPACIO_RECURSO UNION ALL
SELECT 'RESERVA',         COUNT(*) FROM RESERVA;
